-- Billing terms are a reviewed choice, not inferred from the legacy free-text terms.
CREATE TABLE loan_billing_configs (
 loan_id TEXT PRIMARY KEY REFERENCES loans(id), rate_basis_points INTEGER NOT NULL, period_days INTEGER NOT NULL,
 principal_minor INTEGER NOT NULL, currency TEXT NOT NULL, disbursement_date TEXT NOT NULL, reviewed_terms TEXT NOT NULL,
 created_by TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK((rate_basis_points=200 AND period_days IN (30,60)) OR (rate_basis_points=500 AND period_days=180))
);
CREATE TABLE loan_billing_revisions (loan_id TEXT PRIMARY KEY REFERENCES loans(id), revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE loan_billing_config_cancellations (
 id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id), config_request_key TEXT NOT NULL UNIQUE,
 rate_basis_points INTEGER NOT NULL, period_days INTEGER NOT NULL, principal_minor INTEGER NOT NULL, currency TEXT NOT NULL,
 disbursement_date TEXT NOT NULL, reviewed_terms TEXT NOT NULL, config_created_by TEXT NOT NULL,
 reason TEXT NOT NULL CHECK(length(trim(reason))>0), request_key TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE loan_billing_events (
 id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, loan_id TEXT NOT NULL REFERENCES loans(id), config_request_key TEXT NOT NULL,
 event_date TEXT NOT NULL, repayment_id TEXT REFERENCES loan_repayments(id), expected_revision INTEGER NOT NULL,
 total_interest_minor INTEGER NOT NULL, accrued_minor INTEGER NOT NULL, interest_minor INTEGER NOT NULL, principal_minor INTEGER NOT NULL, unapplied_minor INTEGER NOT NULL,
 cash_account_id TEXT, principal_account_id TEXT NOT NULL, receivable_account_id TEXT NOT NULL, income_account_id TEXT NOT NULL, liability_account_id TEXT,
 accrual_journal_id TEXT, repayment_journal_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(total_interest_minor>=0 AND accrued_minor>=0 AND interest_minor>=0 AND principal_minor>=0 AND unapplied_minor>=0),
 CHECK((repayment_id IS NULL AND cash_account_id IS NULL AND repayment_journal_id IS NULL AND interest_minor=0 AND principal_minor=0 AND unapplied_minor=0) OR (repayment_id IS NOT NULL AND cash_account_id IS NOT NULL AND repayment_journal_id IS NOT NULL)),
 CHECK((accrued_minor=0 AND accrual_journal_id IS NULL) OR (accrued_minor>0 AND accrual_journal_id IS NOT NULL)),
 CHECK(unapplied_minor=0 OR liability_account_id IS NOT NULL)
);
CREATE TABLE loan_billing_event_voids (
 id TEXT PRIMARY KEY, event_id TEXT NOT NULL UNIQUE REFERENCES loan_billing_events(id), loan_id TEXT NOT NULL REFERENCES loans(id),
 request_key TEXT NOT NULL UNIQUE, expected_revision INTEGER NOT NULL, reason TEXT NOT NULL,
 created_by TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','final')),
 accrual_reversal_journal_id TEXT, repayment_reversal_journal_id TEXT, effective_date TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER billing_config_insert BEFORE INSERT ON loan_billing_configs BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_config_cancellations WHERE config_request_key=NEW.request_key) THEN RAISE(ABORT,'cancelled configuration key cannot be reused') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loans l WHERE l.id=NEW.loan_id AND l.principal_minor=NEW.principal_minor AND l.currency=NEW.currency AND l.disbursement_date=NEW.disbursement_date AND l.terms=NEW.reviewed_terms AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) OR EXISTS(SELECT 1 FROM loan_repayments r JOIN journal_entries j ON j.source_type='loan-repayment' AND j.source_id=r.id WHERE r.loan_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM loan_term_changes t WHERE t.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id)) THEN RAISE(ABORT,'billing setup changed, unauthorized, has term amendments, or prior repayment journal exists') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j WHERE j.source_type='loan-disbursement' AND j.source_id=NEW.loan_id AND j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries x WHERE x.reverses_entry_id=j.id AND x.status='posted')) THEN RAISE(ABORT,'a posted unreversed loan disbursement is required') END;
END;
CREATE TRIGGER billing_config_revision AFTER INSERT ON loan_billing_configs BEGIN INSERT INTO loan_billing_revisions(loan_id) VALUES(NEW.loan_id) ON CONFLICT(loan_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER billing_config_immutable BEFORE UPDATE ON loan_billing_configs BEGIN SELECT RAISE(ABORT,'billing configuration immutable'); END;
CREATE TRIGGER billing_config_cancel_validate BEFORE INSERT ON loan_billing_config_cancellations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) OR NOT EXISTS(SELECT 1 FROM loan_billing_configs c WHERE c.loan_id=NEW.loan_id AND c.request_key=NEW.config_request_key AND c.rate_basis_points=NEW.rate_basis_points AND c.period_days=NEW.period_days AND c.principal_minor=NEW.principal_minor AND c.currency=NEW.currency AND c.disbursement_date=NEW.disbursement_date AND c.reviewed_terms=NEW.reviewed_terms AND c.created_by=NEW.config_created_by) THEN RAISE(ABORT,'billing configuration changed or has finalized events') END;
END;
CREATE TRIGGER billing_config_cancel_immutable BEFORE UPDATE ON loan_billing_config_cancellations BEGIN SELECT RAISE(ABORT,'billing cancellation immutable'); END;
CREATE TRIGGER billing_config_cancel_no_delete BEFORE DELETE ON loan_billing_config_cancellations BEGIN SELECT RAISE(ABORT,'billing cancellation immutable'); END;
CREATE TRIGGER billing_config_no_delete BEFORE DELETE ON loan_billing_configs WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=OLD.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) OR NOT EXISTS(SELECT 1 FROM loan_billing_config_cancellations WHERE loan_id=OLD.loan_id AND config_request_key=OLD.request_key) BEGIN SELECT RAISE(ABORT,'billing configuration requires reviewed cancellation'); END;
CREATE TRIGGER billing_config_delete_revision AFTER DELETE ON loan_billing_configs BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=OLD.loan_id; END;
CREATE TRIGGER billing_event_immutable BEFORE UPDATE ON loan_billing_events BEGIN SELECT RAISE(ABORT,'billing events immutable'); END;
CREATE TRIGGER billing_event_no_delete BEFORE DELETE ON loan_billing_events BEGIN SELECT RAISE(ABORT,'billing events immutable'); END;
CREATE TRIGGER billing_event_validate BEFORE INSERT ON loan_billing_events BEGIN
 SELECT CASE WHEN NEW.event_date>date('now') THEN RAISE(ABORT,'cannot finalize future billing') END;
 SELECT CASE WHEN NEW.repayment_id IS NOT NULL AND EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.repayment_id=NEW.repayment_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) THEN RAISE(ABORT,'repayment already allocated') END;
 SELECT CASE WHEN NEW.event_date<(SELECT disbursement_date FROM loan_billing_configs WHERE loan_id=NEW.loan_id) THEN RAISE(ABORT,'billing date precedes disbursement') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_revisions WHERE loan_id=NEW.loan_id AND revision=NEW.expected_revision) THEN RAISE(ABORT,'billing review stale or unauthorized') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_configs c JOIN loans l ON l.id=c.loan_id WHERE c.loan_id=NEW.loan_id AND c.request_key=NEW.config_request_key AND l.principal_minor=c.principal_minor AND l.currency=c.currency AND l.disbursement_date=c.disbursement_date AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) THEN RAISE(ABORT,'billing loan changed') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j JOIN journal_lines l ON l.entry_id=j.id AND l.side='debit' WHERE j.source_type='loan-disbursement' AND j.source_id=NEW.loan_id AND j.status='posted' AND l.account_id=NEW.principal_account_id AND NOT EXISTS(SELECT 1 FROM journal_entries x WHERE x.reverses_entry_id=j.id AND x.status='posted')) THEN RAISE(ABORT,'principal account must match posted disbursement') END;
 SELECT CASE WHEN NEW.principal_account_id=NEW.receivable_account_id OR NEW.principal_account_id=NEW.income_account_id OR NEW.receivable_account_id=NEW.income_account_id OR (NEW.cash_account_id IS NOT NULL AND NEW.cash_account_id IN (NEW.principal_account_id,NEW.receivable_account_id,NEW.income_account_id)) OR (NEW.liability_account_id IS NOT NULL AND NEW.liability_account_id IN (NEW.principal_account_id,NEW.receivable_account_id,NEW.income_account_id,NEW.cash_account_id)) THEN RAISE(ABORT,'billing accounts must be distinct') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.principal_account_id AND a.currency=c.currency) OR NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.receivable_account_id AND a.currency=c.currency) OR NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.income_account_id AND a.currency=c.currency) OR (NEW.cash_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.cash_account_id AND a.currency=c.currency)) OR (NEW.liability_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ledger_accounts a JOIN loan_billing_configs c ON c.loan_id=NEW.loan_id WHERE a.id=NEW.liability_account_id AND a.currency=c.currency)) THEN RAISE(ABORT,'billing account missing or currency mismatch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') AND (e.principal_account_id<>NEW.principal_account_id OR e.receivable_account_id<>NEW.receivable_account_id OR e.income_account_id<>NEW.income_account_id)) THEN RAISE(ABORT,'billing accounts cannot change between events') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') AND (e.event_date>NEW.event_date OR (e.event_date=NEW.event_date AND (NEW.repayment_id IS NULL OR e.repayment_id IS NULL OR e.repayment_id>=NEW.repayment_id)))) THEN RAISE(ABORT,'billing must be finalized chronologically') END;
 SELECT CASE WHEN NEW.total_interest_minor<>NEW.accrued_minor+COALESCE((SELECT e.total_interest_minor FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') ORDER BY e.rowid DESC LIMIT 1),0) THEN RAISE(ABORT,'billing accrual total changed') END;
 SELECT CASE WHEN NEW.repayment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM loan_repayments r WHERE r.id=NEW.repayment_id AND r.loan_id=NEW.loan_id AND r.payment_date=NEW.event_date AND r.amount_minor=NEW.interest_minor+NEW.principal_minor+NEW.unapplied_minor AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='repayment' AND v.source_id=r.id) AND NOT EXISTS(SELECT 1 FROM journal_entries j WHERE j.source_type='loan-repayment' AND j.source_id=r.id)) THEN RAISE(ABORT,'repayment changed or already posted') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_repayments r WHERE r.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='repayment' AND v.source_id=r.id) AND NOT EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.repayment_id=r.id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) AND (r.payment_date<NEW.event_date OR (r.payment_date=NEW.event_date AND (NEW.repayment_id IS NULL OR r.id<NEW.repayment_id)))) THEN RAISE(ABORT,'earlier repayment must be finalized first') END;
END;
CREATE TRIGGER billing_event_revision AFTER INSERT ON loan_billing_events BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=NEW.loan_id; END;
CREATE TRIGGER billing_guard_repayment_insert BEFORE INSERT ON loan_repayments WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND e.event_date>=NEW.payment_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) BEGIN SELECT RAISE(ABORT,'repayment predates finalized billing'); END;
CREATE TRIGGER billing_guard_repayment_update BEFORE UPDATE ON loan_repayments WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=OLD.loan_id AND e.event_date>=OLD.payment_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) OR EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.loan_id AND e.event_date>=NEW.payment_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) BEGIN SELECT RAISE(ABORT,'repayment predates finalized billing'); END;
-- Reversal preserves history; it must never make the original source editable.
CREATE TRIGGER billing_posted_repayment_immutable BEFORE UPDATE OF id,loan_id,payment_date,amount_minor ON loan_repayments
WHEN (NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.payment_date IS NOT OLD.payment_date OR NEW.amount_minor IS NOT OLD.amount_minor)
 AND EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.repayment_id=OLD.id AND e.repayment_journal_id IS NOT NULL)
BEGIN SELECT RAISE(ABORT,'billed repayment source is immutable'); END;
CREATE TRIGGER billing_guard_repayment_delete BEFORE DELETE ON loan_repayments WHEN EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=OLD.loan_id AND e.event_date>=OLD.payment_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final')) BEGIN SELECT RAISE(ABORT,'repayment predates finalized billing'); END;
CREATE TRIGGER billing_rep_insert AFTER INSERT ON loan_repayments BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=NEW.loan_id; END;
CREATE TRIGGER billing_rep_update AFTER UPDATE ON loan_repayments BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=OLD.loan_id OR loan_id=NEW.loan_id; END;
CREATE TRIGGER billing_rep_delete AFTER DELETE ON loan_repayments BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=OLD.loan_id; END;
CREATE TRIGGER billing_guard_void BEFORE INSERT ON loan_source_voids WHEN (NEW.source_kind='loan' AND EXISTS(SELECT 1 FROM loan_billing_events e WHERE e.loan_id=NEW.source_id AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final'))) OR (NEW.source_kind='repayment' AND EXISTS(SELECT 1 FROM loan_repayments r JOIN loan_billing_events e ON e.loan_id=r.loan_id AND e.event_date>=r.payment_date AND NOT EXISTS(SELECT 1 FROM loan_billing_event_voids v WHERE v.event_id=e.id AND v.status='final') WHERE r.id=NEW.source_id)) BEGIN SELECT RAISE(ABORT,'source has finalized billing'); END;
CREATE TRIGGER billing_void_revision AFTER INSERT ON loan_source_voids BEGIN UPDATE loan_billing_revisions SET revision=revision+1 WHERE loan_id=CASE WHEN NEW.source_kind='loan' THEN NEW.source_id WHEN NEW.source_kind='repayment' THEN (SELECT loan_id FROM loan_repayments WHERE id=NEW.source_id) END; END;
CREATE TRIGGER billing_loan_guard BEFORE UPDATE ON loans WHEN EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=OLD.id) BEGIN SELECT RAISE(ABORT,'configured billing loan is immutable'); END;
CREATE TRIGGER billing_term_guard BEFORE INSERT ON loan_term_changes WHEN EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) BEGIN SELECT RAISE(ABORT,'configured billing terms are immutable'); END;
CREATE TRIGGER billing_term_void_guard BEFORE INSERT ON loan_term_change_voids WHEN EXISTS(SELECT 1 FROM loan_term_changes t JOIN loan_billing_configs c ON c.loan_id=t.loan_id WHERE t.id=NEW.term_change_id) BEGIN SELECT RAISE(ABORT,'configured billing terms are immutable'); END;
-- Disallow bypassing reviewed allocation via the older manual posting path.
CREATE TRIGGER billing_repayment_manual_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-repayment' AND EXISTS(SELECT 1 FROM loan_repayments r JOIN loan_billing_configs c ON c.loan_id=r.loan_id WHERE r.id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'configured billing requires reviewed allocation'); END;
CREATE TRIGGER billing_repayment_post_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-billing-repayment' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_events e JOIN loan_billing_configs c ON c.loan_id=e.loan_id JOIN loan_repayments r ON r.id=e.repayment_id WHERE e.id=NEW.source_id AND e.repayment_journal_id=NEW.id AND e.created_by=NEW.created_by AND NEW.currency=c.currency AND NEW.effective_date=e.event_date AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id AND side='debit' AND account_id=e.cash_account_id AND amount_minor=r.amount_minor)=1 AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id AND side='debit')=1 AND (SELECT COALESCE(sum(amount_minor),0) FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND account_id=e.principal_account_id)=e.principal_minor AND (SELECT COALESCE(sum(amount_minor),0) FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND account_id=e.receivable_account_id)=e.interest_minor AND (SELECT COALESCE(sum(amount_minor),0) FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND account_id=e.liability_account_id)=e.unapplied_minor AND (SELECT COALESCE(sum(amount_minor),0) FROM journal_lines WHERE entry_id=NEW.id AND side='credit')=r.amount_minor) THEN RAISE(ABORT,'repayment must match billing allocation') END;
END;
CREATE TRIGGER billing_accrual_post_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-billing-accrual' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_billing_events e JOIN loan_billing_configs c ON c.loan_id=e.loan_id WHERE e.id=NEW.source_id AND e.accrual_journal_id=NEW.id AND e.created_by=NEW.created_by AND NEW.currency=c.currency AND NEW.effective_date=e.event_date AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id)=2 AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND side='debit' AND account_id=e.receivable_account_id AND amount_minor=e.accrued_minor) AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND account_id=e.income_account_id AND amount_minor=e.accrued_minor)) THEN RAISE(ABORT,'interest journal must match billing accrual') END;
END;
-- Reversals require an explicit future correction workflow; never leave the event ledger inconsistent.
CREATE TRIGGER billing_reversal_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM loan_billing_events WHERE accrual_journal_id=NEW.reverses_entry_id OR repayment_journal_id=NEW.reverses_entry_id) BEGIN SELECT RAISE(ABORT,'finalized billing reversal requires billing correction'); END;
CREATE TRIGGER billing_disbursement_reversal_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM journal_entries j JOIN loan_billing_configs c ON c.loan_id=j.source_id WHERE j.id=NEW.reverses_entry_id AND j.source_type='loan-disbursement') BEGIN SELECT RAISE(ABORT,'configured billing prevents disbursement reversal'); END;
